public class DeleteConfirmationFlowTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static javax.swing.JButton button(java.awt.Container root, String name) {
        java.awt.Component c = find(root, name);
        return (c instanceof javax.swing.JButton) ? (javax.swing.JButton) c : null;
    }

    public static void main(String[] args) {
        try {
            DeleteConfirmationFlow panel = new DeleteConfirmationFlow();
            javax.swing.JButton delete = button(panel, "deleteButton");
            javax.swing.JButton confirm = button(panel, "confirmButton");
            javax.swing.JButton cancel = button(panel, "cancelButton");
            java.awt.Component status = find(panel, "status");
            check("all three buttons found", true, delete != null && confirm != null && cancel != null);
            check("startup status", "3 items", labelText(status));
            if (delete != null && confirm != null && cancel != null) {
                delete.doClick();
                check("asking for confirmation", "Delete 1 item?", labelText(status));
                check("confirm button becomes usable", true, confirm.isEnabled());
                confirm.doClick();
                check("one item removed", 2, panel.getItemCount());
                check("status back to the count", "2 items", labelText(status));
                delete.doClick();
                cancel.doClick();
                check("cancel removes nothing", 2, panel.getItemCount());
                panel.confirmDelete();
                check("confirm with nothing pending is ignored", 2, panel.getItemCount());
                delete.doClick();
                confirm.doClick();
                delete.doClick();
                confirm.doClick();
                check("delete is blocked at zero items", false, delete.isEnabled());
                panel.requestDelete();
                check("requestDelete at zero items does nothing", "0 items", labelText(status));
            } else {
                failures++;
                System.out.println("FAIL  one or more buttons not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

