import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class DeleteConfirmationFlow extends JPanel {

    private final JButton deleteButton = new JButton("Delete");
    private final JButton confirmButton = new JButton("Yes");
    private final JButton cancelButton = new JButton("No");
    private final JLabel status = new JLabel();

    private int itemCount = 3;
    private boolean pending = false;

    public DeleteConfirmationFlow() {
        deleteButton.setName("deleteButton");
        confirmButton.setName("confirmButton");
        cancelButton.setName("cancelButton");
        status.setName("status");
        add(deleteButton);
        add(confirmButton);
        add(cancelButton);
        add(status);
        deleteButton.addActionListener(e -> requestDelete());
        confirmButton.addActionListener(e -> confirmDelete());
        cancelButton.addActionListener(e -> cancelDelete());
        refresh();
    }

    /** Provided: makes the display match the current state. */
    private void refresh() {
        deleteButton.setEnabled(!pending && itemCount > 0);
        confirmButton.setEnabled(pending);
        cancelButton.setEnabled(pending);
        status.setText(pending ? "Delete 1 item?" : itemCount + " items");
    }

    public int getItemCount() {
        return itemCount;
    }

    public void requestDelete() {
        if (!pending && itemCount > 0) {
            pending = true;
        }
        refresh();
    }

    public void confirmDelete() {
        if (pending) {
            itemCount = itemCount - 1;
            pending = false;
        }
        refresh();
    }

    public void cancelDelete() {
        if (pending) {
            pending = false;
        }
        refresh();
    }
}
